import{_ as n,a as o,c as a,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · 全册语法总结 · can 表能力至过去存在句与时间介词","description":"按课时归集语法规则、原创例句和易错边界。","frontmatter":{"title":"第一册：英语初阶 · 全册语法总结 · can 表能力至过去存在句与时间介词","description":"按课时归集语法规则、原创例句和易错边界。","splitFrom":"life/english/new-concept/book-1/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 全册语法总结","summary":"按课时归集语法规则、原创例句和易错边界。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 全册语法总结 · 主格和宾格至some/any 与存在句疑问","link":"/life/english/new-concept/book-1/grammar-part-02"},"next":{"text":"第一册：英语初阶 · 全册语法总结 · 一般过去时与 did至过去、现在与将来的时间线","link":"/life/english/new-concept/book-1/grammar-part-04"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 全册语法总结 · 主格和宾格至some/any 与存在句疑问","link":"/life/english/new-concept/book-1/grammar-part-02"},"next":{"text":"第一册：英语初阶 · 全册语法总结 · 一般过去时与 did至过去、现在与将来的时间线","link":"/life/english/new-concept/book-1/grammar-part-04"}},"headers":[],"relativePath":"life/english/new-concept/book-1/grammar-part-03.md","filePath":"life/english/new-concept/book-1/grammar-part-03.md"}'),s={name:"life/english/new-concept/book-1/grammar-part-03.md"};function r(i,e,p,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="第一册-英语初阶-·-全册语法总结-·-can-表能力至过去存在句与时间介词" tabindex="-1">第一册：英语初阶 · 全册语法总结 · can 表能力至过去存在句与时间介词 <a class="header-anchor" href="#第一册-英语初阶-·-全册语法总结-·-can-表能力至过去存在句与时间介词" aria-label="Permalink to &quot;第一册：英语初阶 · 全册语法总结 · can 表能力至过去存在句与时间介词&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><h2 id="can-表能力" tabindex="-1">can 表能力 <a class="header-anchor" href="#can-表能力" aria-label="Permalink to &quot;can 表能力 {#can-表能力}&quot;">​</a></h2><p>can 后接动词原形，对所有人称保持 can，不增加 s。否定为 cannot 或 can&#39;t；问句把 can 放在主语前，不另加 do。can 表能力时说明能否完成动作，不等于动作正在发生。副词可说明做得怎样，如 type quickly；形容词常用于描述人或物。</p><p><strong>L45 原创例句：</strong> My colleague can translate this message.</p><p>我的同事能翻译这条信息。</p><p><strong>L46 原创例句：</strong> Can you print the report today?</p><p>你今天能打印报告吗？</p><p><strong>易错：</strong> can 后不能加 to，也不能用第三人称形式 translates。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-045">Lesson 45</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-046">Lesson 46</a></p><h2 id="实义动词的一般现在时问句" tabindex="-1">实义动词的一般现在时问句 <a class="header-anchor" href="#实义动词的一般现在时问句" aria-label="Permalink to &quot;实义动词的一般现在时问句 {#实义动词的一般现在时问句}&quot;">​</a></h2><p>主语为 I/you/we/they 时，实义动词的一般现在时问句通常借助 do；否定用 don&#39;t + 原形。like 表较稳定的喜好，want 表当前想要。Do you like tea? 与 Do you want some tea? 关注点不同。不要在实义动词前错误加 be；回答时用 Yes, I do，不重复整个宾语。</p><p><strong>L47 原创例句：</strong> Do you like coffee without sugar?</p><p>你喜欢不加糖的咖啡吗？</p><p><strong>L48 原创例句：</strong> I do not want a cold drink now.</p><p>我现在不想喝冷饮。</p><p><strong>易错：</strong> 不要把 Do you like 写成 Are you like；这里 like 是动词。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-047">Lesson 47</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-048">Lesson 48</a></p><h2 id="第三人称单数与-does" tabindex="-1">第三人称单数与 does <a class="header-anchor" href="#第三人称单数与-does" aria-label="Permalink to &quot;第三人称单数与 does {#第三人称单数与-does}&quot;">​</a></h2><p>一般现在时主语为 he/she/it 或单个姓名时，肯定句实义动词通常加 s/es。变疑问或否定时由 does 承担人称变化，后面动词恢复原形：Does she like ...? / She doesn&#39;t like ...。不能同时让 does 和 likes 都标记第三人称。meat 通常是不可数名词，谈一类肉不用复数。</p><p><strong>L49 原创例句：</strong> My brother prefers fish to beef.</p><p>我哥哥喜欢鱼胜过牛肉。</p><p><strong>L50 原创例句：</strong> Does your daughter eat carrots?</p><p>你女儿吃胡萝卜吗？</p><p><strong>易错：</strong> Does she eats? 中 eats 应改为 eat；第三人称变化只保留在 does。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-049">Lesson 49</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-050">Lesson 50</a></p><h2 id="come-from-与国籍表达" tabindex="-1">come from 与国籍表达 <a class="header-anchor" href="#come-from-与国籍表达" aria-label="Permalink to &quot;come from 与国籍表达 {#come-from-与国籍表达}&quot;">​</a></h2><p>come from 是实义动词结构，一般现在时问句用 do/does；be from 用 be 提问。Where do you come from? 与 Where are you from? 都可询问来源，但不能混成 Where are you come from?。描述气候常用一般现在时，it 可作天气主语；sunny 等形容词与 rains 等动词结构要区分。</p><p><strong>L51 原创例句：</strong> My neighbours come from Portugal.</p><p>我的邻居来自葡萄牙。</p><p><strong>L52 原创例句：</strong> It is often windy here in spring.</p><p>这里春天经常有风。</p><p><strong>易错：</strong> 天气形容词前用 be；It windy 缺谓语，It is rains 又混合两种结构。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-051">Lesson 51</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-052">Lesson 52</a></p><h2 id="频率副词与天气动词" tabindex="-1">频率副词与天气动词 <a class="header-anchor" href="#频率副词与天气动词" aria-label="Permalink to &quot;频率副词与天气动词 {#频率副词与天气动词}&quot;">​</a></h2><p>always、usually、often、sometimes、never 表频率，通常位于实义动词前、be 后。It often rains 中 rain 是动词；It is often rainy 中 rainy 是形容词。频率不等于眼前进行：often rains 描述规律，is raining 描述此刻。never 已含否定意义，在标准英语中通常不再配 don&#39;t。</p><p><strong>L53 原创例句：</strong> It often rains in this coastal town.</p><p>这座沿海小镇经常下雨。</p><p><strong>L54 原创例句：</strong> The evenings are usually cool in autumn.</p><p>秋天的夜晚通常凉爽。</p><p><strong>易错：</strong> often 在 be 后、普通动词前是常见位置；不要机械认为所有副词都放句尾。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-053">Lesson 53</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-054">Lesson 54</a></p><h2 id="一般现在时的习惯动作" tabindex="-1">一般现在时的习惯动作 <a class="header-anchor" href="#一般现在时的习惯动作" aria-label="Permalink to &quot;一般现在时的习惯动作 {#一般现在时的习惯动作}&quot;">​</a></h2><p>一般现在时描述习惯、规律和相对稳定状态。谈家庭成员时要逐个检查主语：parents 用 go，father 用 goes。时间表达可用 at seven、in the evening、on Mondays。通常活动不必加 now，now 更容易指向正在进行。every day 是时间短语，everyday 是形容词，修饰日常事物。</p><p><strong>L55 原创例句：</strong> My father leaves home at half past seven.</p><p>我父亲每天七点半离家。</p><p><strong>L56 原创例句：</strong> We usually cook dinner together.</p><p>我们通常一起做晚饭。</p><p><strong>易错：</strong> 单数 father 对应 leaves，不能因为句中有 my 就用第一人称形式。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-055">Lesson 55</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-056">Lesson 56</a></p><h2 id="一般现在时与现在进行时" tabindex="-1">一般现在时与现在进行时 <a class="header-anchor" href="#一般现在时与现在进行时" aria-label="Permalink to &quot;一般现在时与现在进行时 {#一般现在时与现在进行时}&quot;">​</a></h2><p>一般现在时说明通常怎样，现在进行时说明现在正在怎样。对比段落可用 usually 与 today/now 建立时间框架。选择时态要看动作意义，而非看到 today 就一律进行时。like、know 等状态动词通常不用进行时表达普通状态。现在进行时既要有 be，也要有动词 ing。</p><p><strong>L57 原创例句：</strong> I usually cycle to work, but today I am taking the bus.</p><p>我通常骑车上班，但今天正在坐公交车。</p><p><strong>L58 原创例句：</strong> Leo is wearing a suit now.</p><p>利奥现在穿着一套西装。</p><p><strong>易错：</strong> 不要写 usually am cycling 来表达普通习惯；先区分稳定规律与临时活动。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-057">Lesson 57</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-058">Lesson 58</a></p><h2 id="可数和不可数名词的数量" tabindex="-1">可数和不可数名词的数量 <a class="header-anchor" href="#可数和不可数名词的数量" aria-label="Permalink to &quot;可数和不可数名词的数量 {#可数和不可数名词的数量}&quot;">​</a></h2><p>可数名词用 many、a few 或具体数词，通常有复数形式；不可数名词用 much、a little 或量词。some 可用于两者。have 作拥有的实义动词时，否定可用 don&#39;t have。购物清单中 a kilo of apples 的数量核心是 kilo，复数时写 two kilos of apples。不要把中文数量词直接省略。</p><p><strong>L59 原创例句：</strong> We need five envelopes and some writing paper.</p><p>我们需要五个信封和一些信纸。</p><p><strong>L60 原创例句：</strong> How much flour do you need?</p><p>你需要多少面粉？</p><p><strong>易错：</strong> flour 为不可数名词，问多少用 much；envelopes 用 many。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-059">Lesson 59</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-060">Lesson 60</a></p><h2 id="have-表身体状况与-must" tabindex="-1">have 表身体状况与 must <a class="header-anchor" href="#have-表身体状况与-must" aria-label="Permalink to &quot;have 表身体状况与 must {#have-表身体状况与-must}&quot;">​</a></h2><p>have 可表达某些身体状况，如 have a headache；be 与形容词搭配，如 be tired。must + 原形可表达强烈要求，但本页只是语言练习，不提供诊断或治疗建议。询问状况可用 What is the matter with ...?，with 后用宾格。第三人称肯定 have 变 has，疑问用 does ... have。</p><p><strong>L61 原创例句：</strong> Mina has a headache today.</p><p>米娜今天头痛。</p><p><strong>L62 原创例句：</strong> What is the matter with him?</p><p>他怎么了？</p><p><strong>易错：</strong> 不要把 has a headache 写成 is a headache；with 后用 him 而非 he。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-061">Lesson 61</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-062">Lesson 62</a></p><h2 id="must-not-与-do-not-have-to" tabindex="-1">must not 与 do not have to <a class="header-anchor" href="#must-not-与-do-not-have-to" aria-label="Permalink to &quot;must not 与 do not have to {#must-not-与-do-not-have-to}&quot;">​</a></h2><p>must not 表示禁止，don&#39;t have to 或 needn&#39;t 表示不必，两者意义不同。You mustn&#39;t enter 是不得进入；You don&#39;t have to enter 是可以不进入。祈使句 Don&#39;t ... 也用于禁令。mustn&#39;t 后跟动词原形。理解规定时先判断是禁止某动作，还是免除义务，不能只因都有 not 就视为同义。</p><p><strong>L63 原创例句：</strong> You must not make noise in this room.</p><p>你不得在这个房间制造噪声。</p><p><strong>L64 原创例句：</strong> You do not have to wait outside.</p><p>你不必在外面等候。</p><p><strong>易错：</strong> mustn&#39;t 不表示“不必”；免除义务应使用 don&#39;t have to。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-063">Lesson 63</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-064">Lesson 64</a></p><h2 id="时间表达与-can-表许可" tabindex="-1">时间表达与 can 表许可 <a class="header-anchor" href="#时间表达与-can-表许可" aria-label="Permalink to &quot;时间表达与 can 表许可 {#时间表达与-can-表许可}&quot;">​</a></h2><p>can 可表示许可，能否这样做需由语境区分能力和允许。询问许可 Can I ...?；答应或拒绝时注意语气。时间表达 half past eight 是八点半，a quarter to nine 是差一刻九点，即八点四十五。at 用在具体钟点前。must be home 强调要求，be home 不是动作 go home。</p><p><strong>L65 原创例句：</strong> Can I stay until a quarter past nine?</p><p>我可以待到九点一刻吗？</p><p><strong>L66 原创例句：</strong> You must be home by half past ten.</p><p>你必须在十点半之前到家。</p><p><strong>易错：</strong> a quarter to nine 是8:45，不是9:15；by 表最迟期限，at 表时点。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-065">Lesson 65</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-066">Lesson 66</a></p><h2 id="be-的过去式-was-were" tabindex="-1">be 的过去式 was/were <a class="header-anchor" href="#be-的过去式-was-were" aria-label="Permalink to &quot;be 的过去式 was/were {#be-的过去式-was-were}&quot;">​</a></h2><p>过去某时的身份、状态或位置可用 was/were。I/he/she/it 用 was，you/we/they 用 were。否定在后面加 not；疑问把 was/were 移到主语前。last weekend、yesterday 指已结束的过去。不要给含 was/were 的问句再加 did；也不要把现在的 are 原样用于过去。</p><p><strong>L67 原创例句：</strong> I was at the library last Saturday.</p><p>上周六我在图书馆。</p><p><strong>L68 原创例句：</strong> Were your friends at the concert yesterday?</p><p>你的朋友昨天在音乐会上吗？</p><p><strong>易错：</strong> Was/Were 自己形成问句，不能写 Did you were ...。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-067">Lesson 67</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-068">Lesson 68</a></p><h2 id="过去存在句与时间介词" tabindex="-1">过去存在句与时间介词 <a class="header-anchor" href="#过去存在句与时间介词" aria-label="Permalink to &quot;过去存在句与时间介词 {#过去存在句与时间介词}&quot;">​</a></h2><p>there was/there were 介绍过去存在的事物，be 的数取决于后面的名词。There were many people 强调过去人多。on 用具体某天或日期，in 用月份年份等，at 用钟点；含 last、next、every 的时间短语通常不再加介词，如 last Sunday。when 询问时间，不等于 where。</p><p><strong>L69 原创例句：</strong> There were hundreds of people at the race.</p><p>比赛现场有数百人。</p><p><strong>L70 原创例句：</strong> The final was on Sunday afternoon.</p><p>决赛在星期日下午。</p><p><strong>易错：</strong> 具体某天下午用 on Sunday afternoon；不是 in Sunday afternoon。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-069">Lesson 69</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-070">Lesson 70</a></p>',107)])])}const d=n(s,[["render",r]]);export{u as __pageData,d as default};
